		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
	);
}

export function toChildArray(children, out) {
	return childReconciler.toChildArray(children, out);
}

