export const childReconciler = new ChildReconciler();

export function diffChildren(
	parentDom,
	renderResult,
	newParentVNode,
	oldParentVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating
) {
	return childReconciler.diffChildren(
		parentDom,
		renderResult,
		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
	);
}

export function toChildArray(children, out) {
	return childReconciler.toChildArray(children, out);
}

export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	return childReconciler.diffProps(dom, newProps, oldProps, isSvg, hydrate);
}

export function setProperty(dom, name, value, oldValue, isSvg) {
	return childReconciler.setProperty(dom, name, value, oldValue, isSvg);
}

export function getDomSibling(vnode, childIndex) {
	return childReconciler.getDomSibling(vnode, childIndex);
}

export function bindContextProvider(provider, contextId, enqueueRender) {
	return childReconciler.bindContextProvider(
		provider,
		contextId,
		enqueueRender
	);
}

export function cloneElement(vnode, props, args) {
	return childReconciler.cloneElement(vnode, props, args);
}

